/* CONTINUUM: HTML/CSS/vanilla JS with Supabase authentication and local-first records. */
const KEY="continuum_data_v1", SESSION="continuum_session_v1";
const EMPTY={inventory:[],planning:[],production:[],machines:[],breakdowns:[],quality:[],inspection:[],dispatch:[],activity:[]};
const ROLES=["Administrator","Inventory Staff","Production Staff","Quality Staff","Dispatch Staff"];
const META={
 inventory:{title:"Inventory",desc:"Manage raw materials, stock movements and reorder levels.",singular:"Inventory Item"},
 planning:{title:"Planning",desc:"Create production plans and check material availability.",singular:"Production Plan"},
 production:{title:"Production",desc:"Monitor output, production losses, machines and maintenance.",singular:"Production Run"},
 quality:{title:"Quality",desc:"Record inspections, accepted quantities, rejects and defects.",singular:"Quality Check"},
 inspection:{title:"Process & Inspection",desc:"Track process stages and final product approval.",singular:"Process Inspection"},
 dispatch:{title:"Dispatch",desc:"Dispatch eligible approved products and retain history.",singular:"Dispatch Record"},
 settings:{title:"Settings & Data",desc:"Back up records and manage the classroom prototype role."}
};
const CFG={
 inventory:{fields:[["name","Material name","text",1],["code","Item code","text",1],["category","Category","select",1,["Raw material","Component","Consumable","Finished product","Other"]],["quantity","Current quantity","number",1],["unit","Unit","select",1,["pcs","kg","g","litre","metre","box","sheet"]],["location","Storage location","text",0],["minLevel","Minimum/reorder level","number",1]],cols:[["name","Material"],["code","Item code"],["category","Category"],["quantity","Quantity"],["location","Location"],["stockStatus","Stock status"]],search:["name","code","category","location"]},
 planning:{fields:[["product","Product / work order","text",1],["plannedQty","Planned quantity","number",1],["date","Production date","date",1],["priority","Priority","select",1,["Low","Normal","High","Urgent"]],["materials","Required material names (comma separated)","text",0],["status","Plan status","select",1,["Planned","Ready","In Progress","Completed","On Hold"]]],cols:[["product","Product / work order"],["plannedQty","Planned"],["date","Date"],["priority","Priority"],["materialStatus","Material availability"],["status","Status"]],search:["product","date","priority","status","materials"]},
 production:{fields:[["planId","Linked production plan","select",1,"plans"],["actualQty","Actual quantity","number",1],["date","Production date","date",1],["shift","Shift","select",1,["Morning","Evening","Night","General"]],["machineId","Machine","select",0,"machines"],["lossReason","Loss reason","select",0,["None","Machine breakdown","Material shortage","Quality rejection","Power interruption","Setup/changeover","Operator issue","Other"]],["notes","Notes","textarea",0]],cols:[["product","Product"],["plannedQty","Planned"],["actualQty","Actual"],["lossQty","Loss"],["machine","Machine"],["date","Date"],["lossReason","Loss reason"]],search:["product","machine","date","lossReason","notes"]},
 quality:{fields:[["productionId","Production run","select",1,"production"],["inspectedQty","Inspected quantity","number",1],["acceptedQty","Accepted quantity","number",1],["rejectedQty","Rejected quantity","number",1],["defect","Defect / reason","text",0],["status","Quality status","select",1,["Pending","Passed","Hold","Rejected"]]],cols:[["product","Product / run"],["inspectedQty","Inspected"],["acceptedQty","Accepted"],["rejectedQty","Rejected"],["defect","Defect / reason"],["status","Status"]],search:["product","defect","status"]},
 inspection:{fields:[["productionId","Production run","select",1,"production"],["stage","Process / stage","select",1,["Cutting","Machining","Assembly","Finishing","Packaging","Final inspection","Other"]],["status","Process status","select",1,["Pending","In Progress","Completed","On Hold"]],["result","Inspection result","select",1,["Not inspected","Passed","Failed","Needs rework"]],["notes","Inspection notes","textarea",0]],cols:[["product","Product / run"],["stage","Process / stage"],["status","Process status"],["result","Inspection result"],["notes","Notes"]],search:["product","stage","status","result","notes"]},
 dispatch:{fields:[["productionId","Approved production run","select",1,"eligibleProduction"],["customer","Customer","text",1],["quantity","Dispatch quantity","number",1],["date","Dispatch date","date",1],["status","Dispatch status","select",1,["Pending","Prepared","Dispatched","On Hold"]],["reference","Dispatch reference","text",0]],cols:[["product","Product"],["customer","Customer"],["quantity","Quantity"],["date","Date"],["reference","Reference"],["status","Status"]],search:["product","customer","date","reference","status"]}
};
function clone(x){return JSON.parse(JSON.stringify(x))}
function load(){try{let x=JSON.parse(localStorage.getItem(KEY)||"null");if(!x||typeof x!=="object")return clone(EMPTY);let clean=clone(EMPTY);for(const k of Object.keys(EMPTY)){if(Array.isArray(x[k]))clean[k]=x[k]}return clean}catch{return clone(EMPTY)}}
let db=load();
function save(){
 localStorage.setItem(KEY,JSON.stringify(db));
 // Cloud record synchronization is intentionally not enabled until the migration
 // and conflict-resolution layer has been configured and tested.
}
function id(prefix="R"){return prefix+"-"+Date.now().toString(36).toUpperCase()+"-"+Math.random().toString(36).slice(2,5).toUpperCase()}
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function n(v){let x=Number(v);return Number.isFinite(x)?x:0}
function today(){return new Date().toISOString().slice(0,10)}
function sess(){try{return JSON.parse(sessionStorage.getItem(SESSION)||"null")}catch{return null}}
function setSess(name,role,extra={}){sessionStorage.setItem(SESSION,JSON.stringify({name,role,...extra}))}
function activityModule(msg){let t=String(msg).toLowerCase();if(/inventory|stock|material/.test(t))return "inventory";if(/plan/.test(t))return "planning";if(/production|machine|breakdown|repair/.test(t))return "production";if(/quality/.test(t))return "quality";if(/inspection|process/.test(t))return "inspection";if(/dispatch/.test(t))return "dispatch";return "other"}
function log(msg,module=null,action=null){let text=String(msg),kind=action||( /^Updated|^Edited/i.test(text)?"updated":/^Deleted/i.test(text)?"deleted":"created");db.activity.unshift({id:id("ACT"),message:text,at:new Date().toISOString(),actor:sess()?.name||"User",module:module||activityModule(text),action:kind});}
function toast(msg){document.querySelector(".toast")?.remove();let d=document.createElement("div");d.className="toast";d.textContent=msg;document.body.append(d);setTimeout(()=>d.remove(),3000)}
function dateFmt(v){if(!v)return"—";let d=new Date(String(v).length===10?v+"T00:00:00":v);return isNaN(d)?"—":d.toLocaleDateString("en-IN",{day:"2-digit",month:"short",year:"numeric"})}
function badge(s){let x=String(s||"Not set").toLowerCase(),c=(/approved|complete|repaired|available|passed|dispatched|accepted|in stock/.test(x)?"good":/pending|planned|progress|repair|hold|low stock|inspection|check materials|urgent|high/.test(x)?"warn":/rejected|failed|critical|out of stock/.test(x)?"bad":"");return `<span class="status ${c}">${esc(s||"Not set")}</span>`}
function getName(arr,key,field="name"){return arr.find(x=>x.id===key)?.[field]||"—"}
function nav(page){
 let links=[["dashboard","index.html","◫","Dashboard"],["inventory","inventory.html","▤","Inventory"],["planning","planning.html","☷","Planning"],["production","production.html","⚙","Production"],["quality","quality.html","✓","Quality"],["inspection","inspection.html","▦","Process & Inspection"],["dispatch","dispatch.html","⇢","Dispatch"]],s=sess()||{name:"Guest",role:"Administrator"};
 return `<aside class="sidebar" id="appSidebar">
 <div class="profile"><div class="avatar">${esc((s.name||"U").slice(0,1).toUpperCase())}</div><div class="profile-meta"><strong>${esc(s.name)}</strong><small>${esc(s.role)}</small></div><span class="profile-chevron">⌄</span></div>
 <div class="side-tabs"><span class="selected">Favorites</span><span>Recently</span></div>
 <div class="nav-label">Dashboards</div><nav>${links.slice(0,1).map(([k,u,i,t])=>`<a class="nav-link ${page===k?"active":""}" href="${u}"><span class="nav-icon">${i}</span>${t}</a>`).join("")}
 <div class="nav-label">Modules</div>${links.slice(1).map(([k,u,i,t])=>`<a class="nav-link ${page===k?"active":""}" href="${u}"><span class="nav-icon">${i}</span><span>${t}</span></a>`).join("")}
 <div class="nav-label">Pages</div><a class="nav-link ${page==="settings"?"active":""}" href="settings.html"><span class="nav-icon">⚙</span><span>Settings & Data</span></a></nav>
 <div class="sidebar-bottom"><div class="sidebar-brand"><img src="continuum-infinity-mark.png" alt=""><span>CONTINUUM</span></div><div class="role-box">SIGNED IN AS<strong>${esc(s.name)}</strong>${esc(s.role)}<button class="button button-small" id="logout">Sign out</button></div></div></aside>`;
}
function rightPanel(){
 const notices=buildNotifications().slice(0,5),acts=db.activity.slice(0,5),s=sess()||{name:"User",role:"Member"};
 return `<aside class="right-panel">
 <section class="right-section"><h2>Notifications</h2>${notices.length?notices.map(x=>`<a class="right-notice" href="${x.href}"><span class="right-symbol">◉</span><span>${esc(x.type)}<small>${esc(x.detail)}</small></span></a>`).join(""):'<p class="right-empty">No new notifications</p>'}</section>
 <section class="right-section"><h2>Activities</h2>${acts.length?acts.map(a=>`<div class="right-activity"><span class="right-avatar">${esc((a.actor||"U").slice(0,1).toUpperCase())}</span><span>${esc(a.message)}<small>${esc(a.actor||"User")} · ${new Date(a.at).toLocaleString("en-IN",{dateStyle:"medium",timeStyle:"short"})}</small></span></div>`).join(""):'<p class="right-empty">No recent activity</p>'}</section>
 <section class="right-section"><h2>Workspace</h2><div class="right-activity"><span class="right-avatar">${esc((s.name||"U").slice(0,1).toUpperCase())}</span><span>${esc(s.name)}<small>${esc(s.role)}</small></span></div></section>
 </aside>`;
}
function shell(page,html){
 let s=sess()||{name:"Student",role:"Administrator"},title=page==="dashboard"?"Default":META[page]?.title||"Dashboard";
 document.getElementById("app").innerHTML=`<div class="app-shell">${nav(page)}<main class="main"><header class="topbar"><button class="top-icon sidebar-toggle" id="sidebarToggle" aria-label="Toggle navigation">◧</button><button class="top-icon" aria-label="Favorite">☆</button><div class="breadcrumb">Dashboards <span>/</span> <strong>${esc(title)}</strong></div><div class="topbar-spacer"></div><label class="top-search"><span>⌕</span><input type="search" placeholder="Search"></label><button class="top-icon" aria-label="Theme">☼</button><button class="top-icon" aria-label="History">◴</button><button class="top-icon" aria-label="Notifications">♧</button><button class="top-icon right-toggle" id="rightToggle" aria-label="Toggle right panel">▥</button><div class="mobile-user">${esc(s.name)}</div></header><section class="content">${html}<div class="footer-note">© 2026 CONTINUUM <span>About　 Support　 Contact</span></div></section></main>${rightPanel()}</div>`;
 document.getElementById("sidebarToggle")?.addEventListener("click",()=>document.getElementById("appSidebar")?.classList.toggle("open"));
 document.getElementById("rightToggle")?.addEventListener("click",()=>document.querySelector(".right-panel")?.classList.toggle("open"));
 document.getElementById("logout")?.addEventListener("click",async()=>{try{if(window.continuumSupabase)await window.continuumSupabase.auth.signOut()}catch(e){console.error(e)}sessionStorage.removeItem(SESSION);location.href="login.html"});
}
function metric(label,value,icon,note){return `<div class="metric-card"><div class="metric-top"><span>${esc(label)}</span><span class="metric-icon">${icon}</span></div><div class="metric-value">${esc(value)}</div><div class="metric-note">${esc(note)}</div></div>`}
function buildNotifications(){
 const out=[];
 db.inventory.filter(x=>n(x.quantity)<=n(x.minLevel)).forEach(x=>out.push({type:"Low stock",detail:`${x.name} is at ${n(x.quantity)} ${x.unit||"units"}; reorder level is ${n(x.minLevel)}.`,href:"inventory.html",level:n(x.quantity)===0?"bad":"warn"}));
 db.breakdowns.filter(x=>x.status!=="Repaired").forEach(x=>out.push({type:"Machine breakdown",detail:`${getName(db.machines,x.machineId)}: ${x.reason} — repair is pending.`,href:"production.html",level:"bad"}));
 db.production.filter(x=>n(x.lossQty)>0).forEach(x=>out.push({type:"Production loss",detail:`${x.product}: ${n(x.lossQty)} units lost against planned output.`,href:"production.html",level:"warn"}));
 db.quality.filter(x=>["Pending","Hold","Rejected"].includes(x.status)).forEach(x=>out.push({type:"Quality attention",detail:`${getName(db.production,x.productionId,"product")}: quality status is ${x.status}.`,href:"quality.html",level:x.status==="Rejected"?"bad":"warn"}));
 db.dispatch.filter(x=>x.status!=="Dispatched").forEach(x=>out.push({type:"Dispatch pending",detail:`${x.product||getName(db.production,x.productionId,"product")} for ${x.customer}: ${x.status}.`,href:"dispatch.html",level:"warn"}));
 db.production.filter(p=>db.quality.some(q=>q.productionId===p.id&&q.status==="Passed")&&db.inspection.some(i=>i.productionId===p.id&&i.stage==="Final inspection"&&i.result==="Passed")&&!db.dispatch.some(d=>d.productionId===p.id)).forEach(p=>out.push({type:"Ready for dispatch",detail:`${p.product} has passed quality and final inspection.`,href:"dispatch.html",level:"good"}));
 return out;
}
function notificationsHTML(){let items=buildNotifications();return `<section class="panel notification-panel"><div class="panel-heading"><div><h2>Notifications & workflow alerts</h2><p>Automatically generated from current saved records</p></div><span class="status ${items.length?"warn":"good"}">${items.length} alert(s)</span></div>${items.length?`<div class="notification-list">${items.map(x=>`<a class="notification-item ${x.level}" href="${x.href}"><span class="notification-dot"></span><span><strong>${esc(x.type)}</strong><small>${esc(x.detail)}</small></span><span class="notification-arrow">→</span></a>`).join("")}</div>`:'<div class="empty"><strong>All clear</strong>No active alerts based on the records currently saved.</div>'}</section>`}
function dashboard(){let low=db.inventory.filter(x=>n(x.quantity)<=n(x.minLevel)).length,planned=db.planning.reduce((s,x)=>s+n(x.plannedQty),0),actual=db.production.reduce((s,x)=>s+n(x.actualQty),0),loss=db.production.reduce((s,x)=>s+n(x.lossQty),0),br=db.breakdowns.filter(x=>x.status!=="Repaired").length,holds=db.quality.filter(x=>["Pending","Hold","Rejected"].includes(x.status)).length,pending=db.dispatch.filter(x=>x.status!=="Dispatched").length,recent=db.activity.slice(0,6);let h=`<div class="page-heading"><div><div class="eyebrow">OPERATIONS OVERVIEW</div><h1>Manufacturing dashboard</h1><p class="page-description">A clear view of your workflow, from raw material to dispatch.</p></div><a class="button button-primary" href="planning.html">＋ Create production plan</a></div><div class="cards">${metric("Inventory items",db.inventory.length,"▦","Saved material records")}${metric("Low-stock items",low,"!","At or below reorder level")}${metric("Planned units",planned.toLocaleString("en-IN"),"▤","Total plan quantities")}${metric("Actual output",actual.toLocaleString("en-IN"),"↗","Recorded production")}${metric("Production loss",loss.toLocaleString("en-IN"),"△","Units lost against plan")}${metric("Open breakdowns",br,"⚙","Awaiting repair")}${metric("Quality holds",holds,"✓","Pending or rejected checks")}${metric("Pending dispatches",pending,"⇢","Not marked dispatched")}</div>${notificationsHTML()}<div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h2>Manufacturing workflow</h2><p>Six connected main modules</p></div></div><div class="workflow">${["Inventory","Planning","Production","Quality","Process & Inspection","Dispatch"].map((x,i)=>(i?'<span class="workflow-arrow">→</span>':"")+`<span class="workflow-step">${x}</span>`).join("")}</div><div class="notice">Maintenance is a supporting function inside Production. Production loss and breakdown history remains saved after repair.</div><div class="panel-heading" style="margin-top:24px"><div><h2>Recent activity</h2><p>Actions recorded in this browser</p></div></div>${recent.length?`<div class="activity-list">${recent.map(a=>activityRow(a)).join("")}</div>`:'<div class="empty"><strong>No activity yet</strong>Add or update records to see activity here.</div>'}</section><section class="panel"><div class="panel-heading"><div><h2>Attention required</h2><p>Based on saved data only</p></div></div>${low?`<div class="activity-text">${low} inventory item(s) at or below minimum stock. <a class="text-link" href="inventory.html">Review →</a></div>`:""}${br?`<div class="activity-text" style="margin-top:12px">${br} machine breakdown(s) still open. <a class="text-link" href="production.html">Review →</a></div>`:""}${holds?`<div class="activity-text" style="margin-top:12px">${holds} quality check(s) need attention. <a class="text-link" href="quality.html">Review →</a></div>`:""}${!low&&!br&&!holds?'<div class="empty"><strong>Nothing flagged</strong>Alerts appear as you add real records.</div>':""}<div class="panel-heading" style="margin-top:24px"><div><h2>Quick actions</h2><p>Go directly to a task</p></div></div><div style="display:flex;gap:8px;flex-wrap:wrap"><a class="button" href="inventory.html">＋ Add material</a><a class="button" href="production.html">＋ Record production</a><a class="button" href="quality.html">＋ Quality check</a><a class="button" href="settings.html">↧ Data backup</a></div></section></div>${analyticsPanel()}`;shell("dashboard",h);bindAnalytics()}
const MODULES=[["inventory","Inventory"],["planning","Planning"],["production","Production"],["quality","Quality"],["inspection","Process & Inspection"],["dispatch","Dispatch"]];
function activityRow(a){return `<div class="activity"><span class="activity-dot"></span><div><div class="activity-text">${esc(a.message)}</div><div class="activity-time">${esc(a.actor||"User")} · ${new Date(a.at).toLocaleString("en-IN")}</div></div></div>`}
function analyticsPanel(){return `<section class="analytics-section"><div class="page-heading"><div><div class="eyebrow">DATA INSIGHTS</div><h2>Analytics & Updates</h2><p class="page-description">Module-wise activity based on actual saved activity logs. No sample or generated chart data.</p></div><div class="analytics-filters"><label>From <input type="date" id="analyticsFrom"></label><label>To <input type="date" id="analyticsTo"></label><label>Module <select id="analyticsModule"><option value="all">All modules</option>${MODULES.map(([k,v])=>`<option value="${k}">${v}</option>`).join("")}</select></label></div></div><div class="analytics-grid"><article class="panel"><div class="panel-heading"><div><h3>Module activity distribution</h3><p>Share of recorded actions in selected range</p></div></div><div class="pie-layout"><div class="pie-chart" id="modulePie"><span>No activity</span></div><div class="chart-legend" id="moduleLegend"></div></div></article><article class="panel"><div class="panel-heading"><div><h3>Activity trend</h3><p>Daily recorded actions in selected range</p></div></div><div class="trend-chart" id="activityTrend"></div></article><article class="panel"><div class="panel-heading"><div><h3>Created vs updated</h3><p>Record actions by module</p></div></div><div class="compare-chart" id="moduleCompare"></div></article><article class="panel analytics-feed"><div class="panel-heading"><div><h3>Recent activity feed</h3><p>Who changed what and when</p></div><span class="status">Live local log</span></div><div id="analyticsFeed" class="activity-list"></div></article></div><p class="analytics-footnote">Analytics reflect actions recorded on this browser. Older records created before this upgrade are classified from their activity descriptions where possible.</p></section>`}
function bindAnalytics(){let end=today(),from=new Date();from.setDate(from.getDate()-29);document.getElementById("analyticsFrom").value=from.toISOString().slice(0,10);document.getElementById("analyticsTo").value=end;["analyticsFrom","analyticsTo","analyticsModule"].forEach(id=>document.getElementById(id).addEventListener("change",renderAnalytics));renderAnalytics()}
function renderAnalytics(){let from=document.getElementById("analyticsFrom").value,to=document.getElementById("analyticsTo").value,mod=document.getElementById("analyticsModule").value;let logs=db.activity.map(a=>({...a,module:a.module||activityModule(a.message),action:a.action||(/^Updated/i.test(a.message)?"updated":/^Deleted/i.test(a.message)?"deleted":"created")})).filter(a=>{let d=String(a.at||"").slice(0,10);return (!from||d>=from)&&(!to||d<=to)&&(mod==="all"||a.module===mod)});let counts=MODULES.map(([key,label])=>({key,label,count:logs.filter(a=>a.module===key).length})),total=counts.reduce((s,x)=>s+x.count,0),colors=["#8a9875","#b58b61","#687d68","#c4aa83","#7e8d91","#a7a18b"];let angle=0,stops=[];counts.forEach((x,i)=>{let next=angle+(total?x.count/total*360:0);stops.push(`${colors[i]} ${angle}deg ${next}deg`);angle=next});let pie=document.getElementById("modulePie");pie.style.background=total?`conic-gradient(${stops.join(",")})`:"#eeeae2";pie.innerHTML=total?`<span>${total}<small>actions</small></span>`:`<span>No activity</span>`;document.getElementById("moduleLegend").innerHTML=counts.map((x,i)=>`<div class="legend-row"><i style="background:${colors[i]}"></i><span>${x.label}</span><b>${total?Math.round(x.count/total*100):0}%</b></div>`).join("");let days=[];if(from&&to){let d=new Date(from+"T00:00:00"),last=new Date(to+"T00:00:00"),max=31;while(d<=last&&days.length<max){let key=d.toISOString().slice(0,10);days.push({key,label:d.toLocaleDateString("en-IN",{day:"2-digit",month:"short"}),count:logs.filter(a=>String(a.at).slice(0,10)===key).length});d.setDate(d.getDate()+1)}}let max=Math.max(1,...days.map(x=>x.count));document.getElementById("activityTrend").innerHTML=days.length?days.map(x=>`<div class="trend-item"><span>${x.label}</span><div><i style="width:${x.count/max*100}%"></i></div><b>${x.count}</b></div>`).join(""):'<div class="empty">Choose a valid date range.</div>';document.getElementById("moduleCompare").innerHTML=counts.map((x,i)=>{let created=logs.filter(a=>a.module===x.key&&a.action!=="updated"&&a.action!=="deleted").length,updated=logs.filter(a=>a.module===x.key&&a.action==="updated").length,scale=Math.max(1,...counts.flatMap(y=>[logs.filter(a=>a.module===y.key&&a.action!=="updated"&&a.action!=="deleted").length,logs.filter(a=>a.module===y.key&&a.action==="updated").length]));return `<div class="compare-row"><span>${x.label}</span><div class="compare-bars"><i class="created" style="width:${created/scale*100}%"></i><i class="updated" style="width:${updated/scale*100}%"></i></div><b>${created}/${updated}</b></div>`}).join("")+`<div class="compare-key"><span><i class="created"></i> Created</span><span><i class="updated"></i> Updated</span></div>`;document.getElementById("analyticsFeed").innerHTML=logs.slice(0,8).length?logs.slice(0,8).map(activityRow).join(""):'<div class="empty">No activity for these filters yet.</div>'}

function optionsFor(f){let o=f[4];if(o==="plans")return db.planning.map(x=>({value:x.id,label:`${x.product} (${x.plannedQty})`}));if(o==="machines")return db.machines.map(x=>({value:x.id,label:x.name}));if(o==="production")return db.production.map(x=>({value:x.id,label:`${x.product} · ${x.date}`}));if(o==="eligibleProduction")return db.production.filter(p=>db.quality.some(q=>q.productionId===p.id&&q.status==="Passed")&&db.inspection.some(i=>i.productionId===p.id&&i.stage==="Final inspection"&&i.result==="Passed")).map(x=>({value:x.id,label:`${x.product} · output ${x.actualQty} (quality + final inspection passed)`}));return (o||[]).map(x=>({value:x,label:x}))}
function field(f,val=""){let [k,label,type,req]=f,ctrl="";if(type==="select"){let opts=optionsFor(f);ctrl=`<select name="${k}" ${req?"required":""}><option value="">Select ${esc(label.toLowerCase())}</option>${opts.map(o=>`<option value="${esc(o.value)}" ${String(val)===String(o.value)?"selected":""}>${esc(o.label)}</option>`).join("")}</select>`}else if(type==="textarea")ctrl=`<textarea name="${k}" ${req?"required":""}>${esc(val)}</textarea>`;else ctrl=`<input name="${k}" type="${type}" ${type==="number"?'min="0" step="any"':""} value="${esc(val)}" ${req?"required":""} placeholder="${esc(label)}">`;return `<div class="field ${type==="textarea"?"full":""}"><label>${esc(label)}${req?" *":""}</label>${ctrl}</div>`}
function valueFor(page,row,k){if(page==="inventory"&&k==="stockStatus")return n(row.quantity)<=n(row.minLevel)?"Low stock":"In stock";if(page==="planning"&&k==="materialStatus"){if(!row.materials)return"Not specified";let names=row.materials.split(",").map(x=>x.trim().toLowerCase()).filter(Boolean);return names.every(name=>db.inventory.some(i=>i.name.toLowerCase()===name&&n(i.quantity)>n(i.minLevel)))?"Available":"Check materials"}if(page==="production"&&k==="machine")return getName(db.machines,row.machineId);if(["quality","inspection"].includes(page)&&k==="product"){let p=db.production.find(x=>x.id===row.productionId);return p?`${p.product} (${p.id})`:"Missing run"}if(page==="dispatch"&&k==="product")return getName(db.production,row.productionId,"product");return row[k]??"—"}
function cell(page,row,k){let v=valueFor(page,row,k);if(["status","stockStatus","materialStatus","priority","result"].includes(k))return badge(v);if(k==="date")return dateFmt(v);if(["plannedQty","actualQty","lossQty","quantity","inspectedQty","acceptedQty","rejectedQty"].includes(k))return n(v).toLocaleString("en-IN");if(["name","product"].includes(k))return `<div class="cell-title">${esc(v)}</div><div class="cell-sub">${esc(row.code||row.id||"")}</div>`;return esc(v)}
function table(page,rows){let c=CFG[page];if(!rows.length)return `<div class="empty"><strong>No ${esc(META[page].title.toLowerCase())} records yet</strong>Add your first record to begin. Saved records appear here.</div>`;return `<div class="table-wrap"><table><thead><tr>${c.cols.map(x=>`<th>${esc(x[1])}</th>`).join("")}<th>Actions</th></tr></thead><tbody>${rows.map(r=>`<tr>${c.cols.map(x=>`<td>${cell(page,r,x[0])}</td>`).join("")}<td><div class="actions">${page==="inventory"?`<button class="button button-small" data-stock="${r.id}" data-move="add">+ Stock</button><button class="button button-small" data-stock="${r.id}" data-move="use">Use</button>`:""}<button class="button button-small" data-edit="${r.id}">Edit</button><button class="button button-small button-danger" data-delete="${r.id}">Delete</button></div></td></tr>`).join("")}</tbody></table></div>`}
function modulePage(page){let m=META[page],c=CFG[page],rows=db[page];let h=`<div class="page-heading"><div><div class="eyebrow">OPERATIONS / ${m.title.toUpperCase()}</div><h1>${m.title}</h1><p class="page-description">${m.desc}</p></div><button class="button button-primary" id="add">＋ Add ${m.singular}</button></div>${page==="production"?maintenanceHTML():""}<section class="panel"><div class="toolbar"><div><strong style="font-size:13px">${rows.length} saved record(s)</strong><div class="cell-sub">Local-first records · cloud sync setup pending</div></div><input id="search" class="search" placeholder="Search ${m.title.toLowerCase()}..."></div><div id="tableArea">${table(page,rows)}</div></section>`;shell(page,h);document.getElementById("add").onclick=()=>modal(page);document.getElementById("search").oninput=e=>{let q=e.target.value.toLowerCase();let rows=db[page].filter(r=>c.search.some(k=>String(valueFor(page,r,k)).toLowerCase().includes(q)));document.getElementById("tableArea").innerHTML=table(page,rows);bindActions(page)};bindActions(page)}
function maintenanceHTML(){return `<section class="panel" style="margin-bottom:18px"><div class="panel-heading"><div><h2>Machine & maintenance support</h2><p>Supporting function inside Production — not a seventh main module.</p></div><div class="actions"><button class="button button-small" id="addMachine">＋ Machine</button><button class="button button-small" id="addBreakdown">＋ Breakdown</button></div></div>${db.machines.length?`<div class="table-wrap"><table><thead><tr><th>Machine</th><th>Code</th><th>Status</th><th>Breakdowns</th></tr></thead><tbody>${db.machines.map(m=>`<tr><td>${esc(m.name)}</td><td>${esc(m.code)}</td><td>${badge(m.status)}</td><td>${db.breakdowns.filter(b=>b.machineId===m.id).length}</td></tr>`).join("")}</tbody></table></div>`:'<div class="empty">No machine records yet. Add a machine to link it to production.</div>'}<h3 style="font-size:12px;margin-top:20px">Breakdown & loss history</h3>${db.breakdowns.length?`<div class="table-wrap"><table><thead><tr><th>Machine</th><th>Reason</th><th>Started</th><th>Status</th><th>Completed</th><th>Linked production</th><th>Action</th></tr></thead><tbody>${db.breakdowns.map(b=>`<tr><td>${esc(getName(db.machines,b.machineId))}</td><td>${esc(b.reason)}</td><td>${dateFmt(b.startDate)}</td><td>${badge(b.status)}</td><td>${dateFmt(b.endDate)}</td><td>${esc(b.productionId?getName(db.production,b.productionId,"product"):"—")}</td><td>${b.status!=="Repaired"?`<button class="button button-small" data-repair="${b.id}">Mark repaired</button>`:"History retained"}</td></tr>`).join("")}</tbody></table></div>`:'<div class="empty">No breakdowns recorded. Historical records remain after repair.</div>'}</section>`}
function bindActions(page){document.querySelectorAll("[data-edit]").forEach(b=>b.onclick=()=>modal(page,b.dataset.edit));document.querySelectorAll("[data-delete]").forEach(b=>b.onclick=()=>del(page,b.dataset.delete));document.querySelectorAll("[data-repair]").forEach(b=>b.onclick=()=>repair(b.dataset.repair));document.querySelectorAll("[data-stock]").forEach(b=>b.onclick=()=>adjustStock(b.dataset.stock,b.dataset.move));document.getElementById("addMachine")?.addEventListener("click",machineModal);document.getElementById("addBreakdown")?.addEventListener("click",breakdownModal)}
function adjustStock(key,move){let item=db.inventory.find(x=>x.id===key);if(!item)return;let label=move==="add"?"Add stock quantity":"Stock usage quantity";let raw=prompt(`${label} for ${item.name}:`);if(raw===null)return;let qty=Number(raw);if(!Number.isFinite(qty)||qty<=0)return toast("Enter a quantity greater than zero.");if(move==="use"&&qty>n(item.quantity))return toast("Stock usage cannot exceed available quantity.");item.quantity=n(item.quantity)+(move==="add"?qty:-qty);log(`${move==="add"?"Added":"Used"} ${qty} ${item.unit} of ${item.name}`);save();modulePage("inventory");toast("Stock updated successfully.")}
function modal(page,editId=null){let c=CFG[page],old=editId?db[page].find(x=>x.id===editId):null;if(page==="production"&&!db.planning.length)return toast("Create a production plan first.");if(["quality","inspection"].includes(page)&&!db.production.length)return toast("Create a production run first.");let html=`<div class="modal-backdrop"><section class="modal"><div class="modal-header"><div><h2>${old?"Edit ":"Add "}${META[page].singular}</h2><p>Fields marked * are required. Data saves in this browser.</p></div><button class="button" data-close>✕</button></div>${page==="production"?'<div class="notice">Loss = planned quantity − actual quantity. Historical loss stays saved after machine repair.</div>':""}<form id="recordForm"><div class="form-grid">${c.fields.map(f=>field(f,old?.[f[0]]??(f[0]==="date"?today():""))).join("")}</div><div class="modal-footer"><button type="button" class="button" data-close>Cancel</button><button class="button button-primary">Save record</button></div></form></section></div>`;document.body.insertAdjacentHTML("beforeend",html);let back=document.querySelector(".modal-backdrop");back.querySelectorAll("[data-close]").forEach(b=>b.onclick=()=>back.remove());back.addEventListener("click",e=>{if(e.target===back)back.remove()});back.querySelector("form").onsubmit=e=>{e.preventDefault();let fd=new FormData(e.target),x={};c.fields.forEach(f=>x[f[0]]=fd.get(f[0]));for(let f of c.fields){if(f[3]&&!String(x[f[0]]??"").trim())return toast("Please complete "+f[1].toLowerCase());if(f[2]==="number"){x[f[0]]=n(x[f[0]]);if(x[f[0]]<0)return toast("Quantity cannot be negative.")}}if(page==="production"){let p=db.planning.find(y=>y.id===x.planId);if(!p)return toast("Select a valid plan.");x.product=p.product;x.plannedQty=n(p.plannedQty);x.lossQty=Math.max(0,x.plannedQty-n(x.actualQty));x.overproduction=Math.max(0,n(x.actualQty)-x.plannedQty);if(x.lossQty&&!x.lossReason)x.lossReason="Not specified";if(n(x.actualQty)>=n(p.plannedQty)&&n(p.plannedQty)>0)p.status="Completed";else if(p.status!=="Completed")p.status="In Progress"}if(page==="quality"&&n(x.acceptedQty)+n(x.rejectedQty)>n(x.inspectedQty))return toast("Accepted + rejected cannot exceed inspected quantity.");if(page==="dispatch"){let p=db.production.find(y=>y.id===x.productionId);if(!p)return toast("Select a run that passed quality and final inspection.");let approved=db.quality.filter(q=>q.productionId===p.id&&q.status==="Passed").reduce((sum,q)=>sum+n(q.acceptedQty),0);let used=db.dispatch.filter(y=>y.productionId===p.id&&y.id!==editId).reduce((sum,y)=>sum+n(y.quantity),0);let limit=Math.min(n(p.actualQty),approved||0);if(n(x.quantity)+used>limit)return toast(`Dispatch quantity exceeds approved accepted quantity. Available for this run: ${Math.max(0,limit-used)}.`);x.product=p.product}if(old)Object.assign(old,x);else{x.id=id(page.slice(0,3).toUpperCase());x.createdAt=new Date().toISOString();db[page].unshift(x)}log(`${old?"Updated":"Added"} ${META[page].singular.toLowerCase()}: ${x.product||x.name||x.stage||x.customer||x.code||x.id}`);save();back.remove();modulePage(page);toast("Record saved successfully.")}}
function del(page,key){let x=db[page].find(y=>y.id===key);if(!x)return;if(!confirm("Delete this record? Related history may still refer to it. Export a backup first if needed."))return;db[page]=db[page].filter(y=>y.id!==key);log(`Deleted ${META[page].singular.toLowerCase()}: ${x.name||x.product||x.id}`);save();modulePage(page);toast("Record deleted.")}
function machineModal(){let b=overlay(`<h2>Add machine</h2><p>Machine records support production and maintenance history.</p>`,[["name","Machine name","text",1],["code","Machine code","text",1],["status","Machine status","select",1,["Available","Under maintenance","Out of service"]]]);b.querySelector("form").onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),m={id:id("MCH"),name:f.get("name"),code:f.get("code"),status:f.get("status")};db.machines.push(m);log("Added machine "+m.name);save();b.remove();modulePage("production");toast("Machine saved.")}}
function breakdownModal(){if(!db.machines.length)return toast("Add a machine first.");let fields=[["machineId","Machine","select",1,"machines"],["productionId","Affected production run (optional)","select",0,"production"],["reason","Breakdown reason","text",1],["startDate","Breakdown start date","date",1]];let b=overlay("<h2>Record machine breakdown</h2><p>Repair updates the status but never deletes history.</p>",fields);b.querySelector("form").onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),x={id:id("BRK"),machineId:f.get("machineId"),productionId:f.get("productionId")||"",reason:f.get("reason"),startDate:f.get("startDate"),status:"Under repair",endDate:""};db.breakdowns.unshift(x);let m=db.machines.find(y=>y.id===x.machineId);if(m)m.status="Under maintenance";let p=db.production.find(y=>y.id===x.productionId);if(p){p.breakdownId=x.id;if(p.lossQty)p.lossReason="Machine breakdown"}log("Recorded machine breakdown: "+x.reason);save();b.remove();modulePage("production");toast("Breakdown saved; history retained.")}}
function overlay(title,fields){let h=`<div class="modal-backdrop"><section class="modal"><div class="modal-header"><div>${title}</div><button class="button" data-close>✕</button></div><form><div class="form-grid">${fields.map(f=>field(f,f[0].includes("Date")?today():"")).join("")}</div><div class="modal-footer"><button type="button" class="button" data-close>Cancel</button><button class="button button-primary">Save</button></div></form></section></div>`;document.body.insertAdjacentHTML("beforeend",h);let b=document.querySelector(".modal-backdrop");b.querySelectorAll("[data-close]").forEach(x=>x.onclick=()=>b.remove());return b}
function repair(key){let b=db.breakdowns.find(x=>x.id===key);if(!b||!confirm("Mark repaired? Breakdown and linked production-loss history will remain saved."))return;b.status="Repaired";b.endDate=today();let still=db.breakdowns.some(x=>x.machineId===b.machineId&&x.id!==b.id&&x.status!=="Repaired"),m=db.machines.find(x=>x.id===b.machineId);if(m)m.status=still?"Under maintenance":"Available";log("Machine repaired; historical loss retained for "+getName(db.machines,b.machineId));save();modulePage("production");toast("Repaired. History retained.")}

async function uploadWorkspaceBackup(){
 const client=authClient(),s=sess();
 if(!client||!s?.workspaceId||!s?.userId)throw Error("Sign in to a company workspace first.");
 const payloads=[
  ["inventory",{inventory:db.inventory,activity:db.activity}],
  ["planning",{planning:db.planning}],
  ["production",{production:db.production,machines:db.machines,breakdowns:db.breakdowns}],
  ["quality",{quality:db.quality}],
  ["inspection",{inspection:db.inspection}],
  ["dispatch",{dispatch:db.dispatch}]
 ];
 for(const [module,data] of payloads){
  const {error}=await client.from("manufacturing_records").upsert({
   workspace_id:s.workspaceId,module,source_id:"__continuum_snapshot_v1__",data,
   created_by:s.userId,updated_by:s.userId,updated_at:new Date().toISOString()
  },{onConflict:"workspace_id,module,source_id"});
  if(error)throw error;
 }
 return payloads.length;
}
async function restoreWorkspaceBackup(){
 const client=authClient(),s=sess();
 if(!client||!s?.workspaceId)throw Error("Sign in to a company workspace first.");
 const {data,error}=await client.from("manufacturing_records").select("module,data").eq("workspace_id",s.workspaceId).eq("source_id","__continuum_snapshot_v1__");
 if(error)throw error;
 if(!data?.length)throw Error("No cloud backup found for this workspace.");
 const next=clone(EMPTY);
 for(const row of data){
  const x=row.data||{};
  if(row.module==="inventory"){next.inventory=Array.isArray(x.inventory)?x.inventory:[];next.activity=Array.isArray(x.activity)?x.activity:[]}
  if(row.module==="planning")next.planning=Array.isArray(x.planning)?x.planning:[];
  if(row.module==="production"){next.production=Array.isArray(x.production)?x.production:[];next.machines=Array.isArray(x.machines)?x.machines:[];next.breakdowns=Array.isArray(x.breakdowns)?x.breakdowns:[]}
  if(row.module==="quality")next.quality=Array.isArray(x.quality)?x.quality:[];
  if(row.module==="inspection")next.inspection=Array.isArray(x.inspection)?x.inspection:[];
  if(row.module==="dispatch")next.dispatch=Array.isArray(x.dispatch)?x.dispatch:[];
 }
 const missing=payloadsMissing(data);
 if(missing.length)throw Error("Cloud backup is incomplete: "+missing.join(", "));
 for(const key of Object.keys(EMPTY)){
  if(!Array.isArray(next[key]))throw Error(`Invalid cloud data in ${key}.`);
  const ids=next[key].map(row=>row?.id).filter(Boolean);
  if(new Set(ids).size!==ids.length)throw Error(`Duplicate IDs found in cloud ${key} data.`);
 }
 if(!confirm("Restore cloud backup and replace records currently stored in this browser? Export a JSON backup first."))
  return false;
 db=next;save();return true;
}
function payloadsMissing(rows){
 const present=new Set(rows.map(x=>x.module));
 return ["inventory","planning","production","quality","inspection","dispatch"].filter(x=>!present.has(x));
}

function settings(){let s=sess()||{name:"Student",role:ROLES[0]};let h=`<div class="page-heading"><div><div class="eyebrow">PREFERENCES / DATA</div><h1>Settings & Data</h1><p class="page-description">${META.settings.desc}</p></div></div><div class="settings-grid"><section class="panel"><div class="panel-heading"><div><h2>Data backup</h2><p>Export all module records to one JSON file.</p></div></div><div class="notice">Includes inventory, plans, production, machine/breakdown history, quality, inspection, dispatch and activity.</div><button class="button button-primary" id="export">↓ Export all data (JSON)</button><div class="field" style="margin-top:22px"><label for="file">Import JSON backup</label><input id="file" type="file" accept=".json,application/json"></div><button class="button" id="import" style="margin-top:10px">↑ Validate & import</button><p class="footer-note">Import replaces current local data after validation and confirmation.</p></section><section class="panel"><div class="panel-heading"><div><h2>Workspace access</h2><p>Your authenticated company workspace.</p></div></div><div class="activity-list"><div class="activity"><div class="activity-text" style="flex:1">Signed-in user</div><strong>${esc(s.name)}</strong></div><div class="activity"><div class="activity-text" style="flex:1">Assigned workspace role</div><strong>${esc(s.role)}</strong></div><div class="activity"><div class="activity-text" style="flex:1">Workspace ID</div><strong style="font-size:10px">${esc(s.workspaceId||"Not linked")}</strong></div></div><div class="notice warning"><strong>Access control status:</strong> Your role is read from Supabase membership and cannot be changed from this screen. Run the included role-security migration in Supabase before inviting staff or using real company data.</div></section><section class="panel"><div class="panel-heading"><div><h2>Current data summary</h2><p>Counts from this browser.</p></div></div><div class="activity-list">${Object.keys(EMPTY).map(k=>`<div class="activity"><div class="activity-text" style="flex:1">${k}</div><strong>${(db[k]||[]).length}</strong></div>`).join("")}</div><button class="button button-danger" id="clear" style="margin-top:16px">Clear all local data</button></section><section class="panel"><div class="panel-heading"><div><h2>Cloud backup</h2><p>Manually transfer this workspace snapshot to Supabase.</p></div></div><div class="notice warning">This is a manual backup/restore tool, not automatic real-time sync. Export a JSON backup before restoring.</div><button class="button button-primary" id="cloudUpload">↑ Upload local records to cloud</button><button class="button" id="cloudRestore" style="margin-left:8px">↓ Restore cloud backup</button><p class="footer-note" id="cloudStatus">Workspace: ${esc(s.workspaceId||"Not linked")}</p></section><section class="panel"><div class="panel-heading"><div><h2>About this prototype</h2><p>Scope and storage.</p></div></div><p style="font-size:12px;line-height:1.8;color:var(--muted)">Built with HTML, CSS and vanilla JavaScript. Supabase email authentication and company workspace creation are connected. Manufacturing records are currently stored in this browser's LocalStorage; cloud sync and cross-device data sharing are pending. Clearing browser storage may erase records, so export backups regularly.</p><div class="notice">Six main modules: Inventory → Planning → Production → Quality → Process & Inspection → Dispatch. Maintenance is a supporting function inside Production.</div></section></div>`;shell("settings",h);document.getElementById("export").onclick=exportData;document.getElementById("import").onclick=importData;document.getElementById("clear").onclick=()=>{if(confirm("Permanently clear all records in this browser? Export a backup first if needed.")){db=clone(EMPTY);save();settings();toast("Local data cleared.")}};
 const status=document.getElementById("cloudStatus");
 document.getElementById("cloudUpload").onclick=async()=>{const b=document.getElementById("cloudUpload");b.disabled=true;b.textContent="Uploading…";try{const count=await uploadWorkspaceBackup();status.textContent=`Uploaded ${count} module snapshots to the signed-in workspace.`;toast("Cloud backup uploaded.")}catch(e){status.textContent="Upload failed: "+e.message;toast("Cloud backup failed.")}finally{b.disabled=false;b.textContent="↑ Upload local records to cloud"}};
 document.getElementById("cloudRestore").onclick=async()=>{const b=document.getElementById("cloudRestore");b.disabled=true;b.textContent="Restoring…";try{const ok=await restoreWorkspaceBackup();if(ok){settings();toast("Cloud backup restored.")}}catch(e){status.textContent="Restore failed: "+e.message;toast("Cloud restore failed.")}finally{b.disabled=false;b.textContent="↓ Restore cloud backup"}};
}
function exportData(){let blob=new Blob([JSON.stringify({application:"CONTINUUM",version:1,exportedAt:new Date().toISOString(),data:db},null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="continuum-backup-"+today()+".json";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast("JSON backup exported.")}
function importData(){
 const file=document.getElementById("file").files[0];
 if(!file)return toast("Choose a JSON file first.");
 const reader=new FileReader();
 reader.onload=()=>{
  try{
   const parsed=JSON.parse(reader.result),source=parsed?.data||parsed,keys=Object.keys(EMPTY);
   if(!source||typeof source!=="object"||keys.some(k=>!Array.isArray(source[k])))throw Error("Missing required CONTINUUM data arrays.");
   const next=clone(EMPTY);keys.forEach(k=>next[k]=source[k]);
   for(const key of keys){
    if(next[key].some(row=>!row||typeof row!=="object"||Array.isArray(row)))throw Error(`Invalid record found in ${key}.`);
    const ids=next[key].map(row=>row.id).filter(Boolean);
    if(new Set(ids).size!==ids.length)throw Error(`Duplicate record IDs found in ${key}.`);
   }
   const prod=new Map(next.production.map(row=>[row.id,row])),plans=new Map(next.planning.map(row=>[row.id,row])),machines=new Map(next.machines.map(row=>[row.id,row]));
   const validRef=(value,map)=>!value||map.has(value);
   if(next.production.some(row=>!validRef(row.planId,plans)||!validRef(row.machineId,machines)))throw Error("A production run references a missing plan or machine.");
   if(next.breakdowns.some(row=>!validRef(row.machineId,machines)||!validRef(row.productionId,prod)))throw Error("A breakdown references a missing machine or production run.");
   if(["quality","inspection","dispatch"].some(key=>next[key].some(row=>!validRef(row.productionId,prod))))throw Error("A quality, inspection, or dispatch record references a missing production run.");
   const numericFields={inventory:["quantity","minLevel"],planning:["plannedQty"],production:["actualQty","plannedQty","lossQty","overproduction"],quality:["inspectedQty","acceptedQty","rejectedQty"],dispatch:["quantity"]};
   for(const [key,fields] of Object.entries(numericFields))for(const row of next[key])for(const field of fields)if(row[field]!==undefined&&(!Number.isFinite(Number(row[field]))||Number(row[field])<0))throw Error(`Invalid non-negative quantity in ${key}.`);
   if(next.quality.some(row=>n(row.acceptedQty)+n(row.rejectedQty)>n(row.inspectedQty)))throw Error("A quality record has accepted + rejected quantity greater than inspected quantity.");
   const passedQuality=new Map();
   next.quality.filter(row=>row.status==="Passed").forEach(row=>passedQuality.set(row.productionId,(passedQuality.get(row.productionId)||0)+n(row.acceptedQty)));
   const eligible=new Set(next.production.filter(row=>next.inspection.some(i=>i.productionId===row.id&&i.stage==="Final inspection"&&i.result==="Passed")&&(passedQuality.get(row.id)||0)>0).map(row=>row.id));
   const dispatchTotals=new Map();
   for(const row of next.dispatch){
    if(!eligible.has(row.productionId))throw Error("A dispatch record lacks passed quality and final inspection approval.");
    const run=prod.get(row.productionId),sum=(dispatchTotals.get(row.productionId)||0)+n(row.quantity),limit=Math.min(n(run.actualQty),passedQuality.get(row.productionId)||0);
    if(sum>limit)throw Error("Dispatch quantities exceed the approved accepted quantity for a production run.");
    dispatchTotals.set(row.productionId,sum);
   }
   if(!confirm("This replaces the current records in this browser. Continue?"))return;
   db=next;save();settings();toast("JSON imported successfully.");
  }catch(error){toast("Import failed: "+error.message)}
 };
 reader.readAsText(file);
}
function authClient(){
 if(window.continuumSupabase)return window.continuumSupabase;
 const cfg=window.CONTINUUM_SUPABASE_CONFIG;
 if(!cfg||!window.supabase?.createClient)return null;
 window.continuumSupabase=window.supabase.createClient(cfg.url,cfg.publishableKey);
 return window.continuumSupabase;
}
async function finishAuthenticatedLogin(client,user,companyName=""){
 let {data:members,error}=await client.from("workspace_members").select("workspace_id,role,active").eq("user_id",user.id).eq("active",true).limit(1);
 if(error)throw error;
 let membership=members?.[0];
 if(!membership){
  const pending=companyName||user.user_metadata?.company_name||localStorage.getItem("continuum_pending_workspace")||"CONTINUUM Workspace";
  const {data:workspaceId,error:createError}=await client.rpc("create_workspace",{workspace_name:pending});
  if(createError)throw createError;
  membership={workspace_id:workspaceId,role:"Administrator",active:true};
  localStorage.removeItem("continuum_pending_workspace");
 }
 const name=user.user_metadata?.full_name||user.email?.split("@")[0]||"CONTINUUM User";
 const role=membership.role==="Administrator"?"Administrator":membership.role;
 setSess(name,role,{userId:user.id,workspaceId:membership.workspace_id,email:user.email});
 location.href="index.html";
}
function login(){
 const client=authClient();
 document.getElementById("app").innerHTML=`<main class="login-page login-reference-layout"><section class="login-reference-card"><div class="login-reference-form-side"><header class="login-reference-brand"><img class="login-logo-lockup" src="continuum-logo-lockup.png" alt="CONTINUUM — Manufacturing Process Management" /></header><form class="login-form" id="loginForm"><div class="eyebrow">SECURE WORKSPACE</div><h2>Enter CONTINUUM</h2><p>Sign in to your company workspace or register a new company.</p><div class="field"><label>Full name</label><input name="name" required maxlength="60" placeholder="Your full name"></div><div class="field"><label>Company / workspace name (new company only)</label><input name="company" maxlength="100" placeholder="e.g. ABC Manufacturing"></div><div class="field"><label>Email address</label><input name="email" type="email" required autocomplete="email" placeholder="name@company.com"></div><div class="field"><label>Password</label><input name="password" type="password" required minlength="8" autocomplete="current-password" placeholder="At least 8 characters"></div><div id="authMessage" class="notice" style="display:none" role="status"></div><button class="button button-primary" id="signInButton" style="width:100%;margin-top:8px">Sign in →</button><button class="button" id="signUpButton" type="button" style="width:100%;margin-top:9px">Register new company</button><div class="footer-note">Email confirmation may be required. Company registration creates the first Administrator account. Employee invitations will be managed by the company Administrator.</div></form></div><aside class="login-reference-art" aria-hidden="true"><div class="art-orbit orbit-one"></div><div class="art-orbit orbit-two"></div><div class="art-dashboard"><div class="art-sidebar"><i></i><i></i><i></i><i></i></div><div class="art-chart"><b></b><b></b><b></b><b></b><span></span></div><div class="art-lines"><i></i><i></i><i></i><i></i></div><div class="art-bars"><i></i><i></i><i></i><i></i><i></i></div></div><div class="art-person person-one"><i></i><b></b><span></span></div><div class="art-person person-two"><i></i><b></b><span></span></div><div class="art-caption">A clearer view of every manufacturing stage</div></aside></section><footer class="login-bottom-bar"><span>INTEGRATED WORKFLOW</span><span>A continuous flow for smarter manufacturing — from inventory to dispatch.</span></footer></main>`;
 const form=document.getElementById("loginForm"),message=document.getElementById("authMessage");
 const show=(txt,bad=false)=>{message.style.display="block";message.textContent=txt;message.className="notice"+(bad?" warning":"")};
 if(!client){show("Supabase client could not load. Check your internet connection and project configuration.",true);return}
 document.getElementById("signInButton").onclick=async e=>{
  e.preventDefault();const f=new FormData(form),email=String(f.get("email")).trim(),password=String(f.get("password"));
  if(!email||!password)return show("Enter your email and password.",true);
  const btn=document.getElementById("signInButton");btn.disabled=true;btn.textContent="Signing in…";
  try{const {data,error}=await client.auth.signInWithPassword({email,password});if(error)throw error;await finishAuthenticatedLogin(client,data.user)}
  catch(err){show(err.message||"Sign in failed.",true);btn.disabled=false;btn.textContent="Sign in →"}
 };
 document.getElementById("signUpButton").onclick=async()=>{
  const f=new FormData(form),name=String(f.get("name")).trim(),company=String(f.get("company")).trim(),email=String(f.get("email")).trim(),password=String(f.get("password"));
  if(!name||!company||!email||password.length<8)return show("For company registration, enter your name, company name, email and a password of at least 8 characters.",true);
  const btn=document.getElementById("signUpButton");btn.disabled=true;btn.textContent="Creating account…";
  try{
   localStorage.setItem("continuum_pending_workspace",company);
   const {data,error}=await client.auth.signUp({email,password,options:{data:{full_name:name,company_name:company},emailRedirectTo:location.origin+location.pathname}});
   if(error)throw error;
   if(data.session&&data.user){await finishAuthenticatedLogin(client,data.user,company)}
   else show("Registration started. Check your email and confirm your address, then return here and sign in. Your company workspace will be created on first sign-in.");
  }catch(err){show(err.message||"Registration failed.",true);localStorage.removeItem("continuum_pending_workspace")}
  finally{btn.disabled=false;btn.textContent="Register new company"}
 };
}
async function init(){
 if("serviceWorker" in navigator && location.protocol!=="file:")navigator.serviceWorker.register("./sw.js").catch(()=>{});
 const p=document.body.dataset.page,client=authClient();
 if(p==="login"){
  if(client){const {data}=await client.auth.getSession();if(data?.session){try{await finishAuthenticatedLogin(client,data.session.user)}catch(e){console.error(e)}}}
  if(!sess())login();
  return;
 }
 if(client){
  const {data,error}=await client.auth.getSession();
  if(error||!data?.session){sessionStorage.removeItem(SESSION);location.replace("login.html");return}
  if(!sess()) {
   try{await finishAuthenticatedLogin(client,data.session.user)}catch(e){console.error(e);location.replace("login.html");return}
   return;
  }
 } else if(!sess()){location.replace("login.html");return}
 if(p==="dashboard")dashboard();else if(p==="settings")settings();else if(CFG[p])modulePage(p);else dashboard();
}
document.addEventListener("DOMContentLoaded",()=>{init().catch(error=>{console.error(error);const el=document.getElementById("app");if(el)el.innerHTML='<div class="notice warning">CONTINUUM could not initialize. Check the connection and reload.</div>'})});
